package com.flippingfriend.companion;
import org.junit.Test; import static org.junit.Assert.*;
public class BuyReplacementWorstLossEvaluatorTest {
 @Test public void appliesProductionMultiplicationCastAndFloorInOrder(){BuyReplacementWorstLossInputContext s=source();BuyReplacementWorstLossEvaluationSet r=new BuyReplacementWorstLossEvaluator().evaluate(s,1100);assertNotNull(r);assertEquals(s.getEvaluations().size(),r.getEvaluations().size());for(int i=0;i<r.getEvaluations().size();i++){BuyReplacementExpectedProfitEvaluation a=s.getEvaluations().get(i);BuyReplacementWorstLossEvaluation e=r.getEvaluations().get(i);long expected=Math.max(1,(long)(a.getBuyPrice()*s.getLossCutPct()*a.getExactRemainderQuantity()));assertEquals(expected,e.getWorstLoss());assertEquals(s.getLossCutPct(),e.getLossCutPct(),0.0);assertEquals(a.getSellOffsetIndex(),e.getSellOffsetIndex());assertEquals(a.getExpectedProfit(),e.getExpectedProfit(),0.0);}try{r.getEvaluations().clear();fail("immutable");}catch(UnsupportedOperationException expected){}}
 @Test public void unavailableAndStaleInputsFailClosed(){BuyReplacementWorstLossEvaluator e=new BuyReplacementWorstLossEvaluator();assertNull(e.evaluate(null,1100));assertNull(e.evaluate(source(),1221));}
 @Test public void contractsCarryNoSizingThroughputRankingSelectionOrAuthorization()throws Exception{for(String f:new String[]{"BuyReplacementWorstLossEvaluation.java","BuyReplacementWorstLossEvaluationSet.java"}){String x=java.nio.file.Files.readString(java.nio.file.Path.of("src/main/java/com/flippingfriend/companion/"+f));for(String forbidden:new String[]{"kelly","expectedGpPerSlotHour","positionSize","selected","score","rank","PortfolioCandidate","PolicyDecision","OfferLifecycleAction","REPLACEMENT_AUTHORIZED"})assertFalse(x.contains(forbidden));}}
 static BuyReplacementWorstLossEvaluationSet evaluationSetForCompanionTests(){return new BuyReplacementWorstLossEvaluator().evaluate(source(),1100);} private static BuyReplacementWorstLossInputContext source(){return BuyReplacementWorstLossInputContextComposerTest.evaluationContextForCompanionTests();}
}
